INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch13$PT132-S4-Q7$batch13$, 132, 4, 7, $batch13$Paradox$batch13$, $batch13$Researcher: Over the course of three decades, we kept records of the average beak size of two populations of the same species of bird, one wild population, the other captive. During this period, the average beak size of the captive birds did not change, while the average beak size of the wild birds decreased significantly.$batch13$, $batch13$Which one of the following, if true, most helps to explain the researcher's findings?$batch13$, $batch13$C$batch13$, true, $batch13$Batch 13; question text from local bank.$batch13$ FROM lr_sections s WHERE s.preptest=132 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT132-S4-Q7$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$A$batch13$, $batch13$The small-beaked wild birds were easier to capture and measure than the large-beaked wild birds.$batch13$, $batch13$Incomplete$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT132-S4-Q7$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$A$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$B$batch13$, $batch13$The large-beaked wild birds were easier to capture and measure than the small-beaked wild birds.$batch13$, $batch13$Opposite$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT132-S4-Q7$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$B$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$C$batch13$, $batch13$Changes in the wild birds' food supply during the study period favored the survival of small-beaked birds over large-beaked birds.$batch13$, $batch13$Correct$batch13$, true FROM lr_questions q WHERE q.qid=$batch13$PT132-S4-Q7$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$C$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$D$batch13$, $batch13$The average body size of the captive birds remained the same over the study period.$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT132-S4-Q7$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$D$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$E$batch13$, $batch13$The researcher measured the beaks of some of the wild birds on more than one occasion.$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT132-S4-Q7$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$E$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT132-S4-Q7$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Fact$batch13$, $batch13$Over three decades, the average beak size of a captive population stayed the same, while the average beak size of a wild population of the same species shrank significantly.$batch13$), (1, $batch13$Evaluate$batch13$, $batch13$Same species, different trends. Something about life in the wild changed beak size there and not in captivity. Natural selection is the obvious candidate.$batch13$), (2, $batch13$Goal$batch13$, $batch13$Find a pressure in the wild that favored small beaks over time.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT132-S4-Q7$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$This is the trap. If small-beaked birds were always easier to catch, every wild average would come out small. That doesn't explain a decrease over time.$batch13$), ($batch13$B$batch13$, $batch13$This would make the wild average look larger, not smaller.$batch13$), ($batch13$C$batch13$, $batch13$A changing food supply favored small-beaked birds, so more of them survived and the average shrank. Captive birds weren't exposed to it.$batch13$), ($batch13$D$batch13$, $batch13$The captive birds' body size says nothing about why wild beaks shrank.$batch13$), ($batch13$E$batch13$, $batch13$Measuring some birds twice doesn't produce a steady trend.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT132-S4-Q7$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
